import json
import sys
import os
from datetime import datetime

def parse_date(date_str):
    if not date_str:
        return None
    try:
        # Handle potential space in timestamp like "2024-02-16 00:00:00"
        return datetime.strptime(date_str.split(' ')[0], '%Y-%m-%d')
    except ValueError:
        return None

